namespace Fanex.Tarus.Customer.DataAccess.CustomerLogin
{
    using System;
    using System.Diagnostics.CodeAnalysis;
    using Fanex.Data;
    using Fanex.Tarus.Customer.Criteria.CustomerLogin;
    using Fanex.Tarus.Customer.Entities;

    [SuppressMessage("Microsoft.StyleCop.CSharp.DocumentationRules", "SA1600:ElementsMustBeDocumented")]
    public class CustomerOTPDataAccess : ICustomerOTPDataAccess
    {
        public Result RemoveOTP(RemoveOTPCriteria criteria)
        {
            if (criteria == null)
            {
                throw new ArgumentNullException(nameof(criteria), "Criteria cannot be null");
            }

            using (var db = new ObjectDb(criteria.GetSettingKey()))
            {
                db.ExecuteNonQuery(criteria.GetSpParams());
                var outputParams = db.GetOuputParams();
                var code = (int)outputParams["errcode"];

                return new Result
                {
                    ErrorCode = code,
                    ErrorMessage = outputParams["errmsg"].ToString()
                };
            }
        }
    }
}
